{"action":"write_file","path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Alpine Reverie — Interactive Snow Globe</title>
<style>
  :root{--ink:#183749;--muted:#5f7683;--blue:#2f718e;--paper:#f8fbfa;--line:rgba(39,79,95,.16)}
  *{box-sizing:border-box}
  html,body{height:100%;margin:0;overflow:hidden}
  body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#e9f0ef}
  button{font:inherit}
  .page{position:relative;isolation:isolate;display:grid;grid-template-rows:auto 1fr auto;min-height:100%;padding:26px clamp(22px,4vw,64px) 20px;overflow:hidden;background:radial-gradient(circle at 50% 46%,#fff 0 24%,transparent 56%),linear-gradient(135deg,#f8faf7,#dce9e9)}
  .page:before{content:"";position:absolute;inset:0;z-index:-2;opacity:.25;background-image:linear-gradient(rgba(28,66,82,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(28,66,82,.04) 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(to bottom,black,transparent 76%)}
  .orb{position:absolute;border:1px solid rgba(57,103,119,.16);border-radius:50%;z-index:-1}.orb.one{width:380px;height:380px;left:-190px;top:18%}.orb.two{width:230px;height:230px;right:-70px;top:12%}.orb.three{width:100px;height:100px;right:14%;bottom:12%}
  header{display:flex;justify-content:space-between;align-items:flex-start;z-index:2}
  .brand{display:flex;align-items:center;gap:12px;font-weight:750;letter-spacing:.12em;font-size:12px;text-transform:uppercase}.brand-mark{width:34px;height:34px;border:1px solid var(--ink);border-radius:50%;display:grid;place-items:center}.brand-mark svg{width:20px}
  .edition{text-align:right;font:500 10px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.13em;text-transform:uppercase;color:var(--muted)}
  main{min-height:0;position:relative;display:grid;grid-template-columns:minmax(210px,1fr) minmax(390px,640px) minmax(210px,1fr);align-items:center;gap:3vw}
  .copy{align-self:center;max-width:330px;padding-bottom:7vh}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--blue);font:650 11px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.16em;text-transform:uppercase}.eyebrow:before{content:"";width:31px;height:1px;background:var(--blue)}
  h1{font-family:Georgia,"Times New Roman",serif;font-size:clamp(46px,5.5vw,84px);font-weight:400;letter-spacing:-.055em;line-height:.87;margin:22px 0 23px}h1 em{display:block;color:var(--blue);font-weight:400}
  .copy p{font-size:13px;line-height:1.8;color:var(--muted);max-width:270px;margin:0}
  .scene{height:min(72vh,720px);min-height:440px;position:relative;display:grid;place-items:center;touch-action:none;cursor:grab}.scene:active{cursor:grabbing}canvas{position:absolute;width:100%;height:100%;inset:0;filter:drop-shadow(0 30px 28px rgba(32,63,71,.14))}
  .hint{position:absolute;bottom:3%;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;color:#6d828c;font:600 9px ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.13em;text-transform:uppercase;white-space:nowrap;transition:opacity .4s}.hint svg{width:21px;height:21px;border:1px solid var(--line);border-radius:50%;padding:4px}
  .panel{justify-self:end;width:min(100%,230px);align-self:center;padding-bottom:4vh}.fact{border-top:1px solid var(--line);padding:16px 0 20px}.fact-label{font:600 9px ui-monospace,SFMono-Regular,Menlo,monospace;color:#82949c;letter-spacing:.15em;text-transform:uppercase}.fact-value{font-family:Georgia,serif;font-size:21px;margin-top:6px;color:#284c5e}.fact-value small{font:500 11px ui-sans-serif,system-ui;color:var(--muted)}
  .controls{display:flex;gap:10px;margin-top:8px}.btn{height:42px;border-radius:999px;border:1px solid var(--ink);background:transparent;color:var(--ink);padding:0 18px;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:.2s}.btn:hover,.btn:focus-visible{background:var(--ink);color:#fff;transform:translateY(-1px)}.btn.primary{background:var(--ink);color:white}.btn.primary:hover{background:var(--blue)}
  footer{display:flex;justify-content:space-between;align-items:end;font:500 9px ui-monospace,SFMono-Regular,Menlo,monospace;text-transform:uppercase;letter-spacing:.13em;color:#7a8d95}.status{display:flex;align-items:center;gap:7px}.status i{width:6px;height:6px;border-radius:50%;background:#6f9e8e;box-shadow:0 0 0 4px rgba(111,158,142,.12)}
  .temp{font-family:Georgia,serif;font-size:18px;color:var(--ink);letter-spacing:0;text-transform:none}
  @media(max-width:900px){main{grid-template-columns:1fr minmax(360px,1.7fr)}.panel{display:none}.copy{padding-bottom:0}h1{font-size:clamp(44px,8vw,68px)}}
  @media(max-width:650px){.page{padding:20px 18px 16px}.edition{display:none}main{display:block}.copy{position:absolute;z-index:3;top:6%;left:2%;pointer-events:none}.copy p{display:none}h1{font-size:45px;margin:14px 0}.scene{height:76vh;min-height:480px;margin-top:35px}.hint{bottom:0}footer>span:nth-child(2){display:none}}
</style>
</head>
<body>
<div class="page">
  <i class="orb one"></i><i class="orb two"></i><i class="orb three"></i>
  <header>
    <div class="brand"><span class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M3 18 9.2 8l2.6 4L15 6l6 12H3Z"/><path d="m7.4 11 1.8 1.2 1.1-1.1M12.8 10l2.1 1.5 1.7-1.3"/></svg></span>North & Still</div>
    <div class="edition">Field object no. 07<br>45.8326° N, 6.8652° E</div>
  </header>
  <main>
    <section class="copy">
      <div class="eyebrow">A quiet place</div>
      <h1>Alpine<br><em>Reverie.</em></h1>
      <p>A small winter held in glass. Turn the globe, wake the snow, and linger awhile beneath the summit.</p>
    </section>
    <section class="scene" id="scene" aria-label="Interactive snow globe with a snowy mountain scene">
      <canvas id="globe"></canvas>
      <div class="hint" id="hint"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M8 8 4 12l4 4M16 8l4 4-4 4M4 12h16"/></svg>Drag to turn</div>
    </section>
    <aside class="panel">
      <div class="fact"><div class="fact-label">Summit</div><div class="fact-value">4,808 <small>m</small></div></div>
      <div class="fact"><div class="fact-label">Atmosphere</div><div class="fact-value">Soft snowfall</div></div>
      <div class="fact"><div class="fact-label">Local time</div><div class="fact-value" id="clock">18:42</div></div>
      <div class="controls"><button class="btn primary" id="shake">Shake</button><button class="btn" id="reset" aria-label="Reset view">Reset</button></div>
    </aside>
  </main>
  <footer><span class="status"><i></i>Scene active</span><span>Made for slow moments</span><span class="temp">−8°C</span></footer>
</div>
<script>
(function(){
'use strict';
const canvas=document.getElementById('globe'),ctx=canvas.getContext('2d'),scene=document.getElementById('scene'),hint=document.getElementById('hint');
let W=0,H=0,dpr=1,cx=0,cy=0,R=0,yaw=0,targetYaw=0,drag=false,lastX=0,energy=.4,time=0;
const flakes=[],trees=[];
function rand(a,b){return a+Math.random()*(b-a)}
for(let i=0;i<170;i++) flakes.push({x:rand(-1,1),y:rand(-1,1),z:rand(-1,1),s:rand(.6,2.3),v:rand(.0015,.004),w:rand(0,6.28)});
for(let i=0;i<23;i++) trees.push({a:rand(-1.3,1.3),z:rand(-.2,.7),s:rand(.55,1.1)});
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);cx=W/2;cy=H*.43;R=Math.min(W*.43,H*.37)}
addEventListener('resize',resize);resize();
function path(points){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath()}
function tree(x,y,s,alpha){ctx.save();ctx.translate(x,y);ctx.globalAlpha=alpha;ctx.fillStyle='#183f48';ctx.fillRect(-.8*s,0,1.6*s,6*s);ctx.fillStyle='#285c61';for(let j=0;j<3;j++){const yy=-j*6*s;path([[0,-20*s+yy],[-8*s,2*s+yy],[8*s,2*s+yy]]);ctx.fill()}ctx.restore()}
function drawBase(){
  const by=cy+R*.8,bw=R*1.3,bh=R*.31;
  let g=ctx.createLinearGradient(0,by,0,by+bh);g.addColorStop(0,'#47666d');g.addColorStop(.12,'#244852');g.addColorStop(.5,'#193944');g.addColorStop(1,'#0b2631');
  ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(cx,by,bw*.48,bh*.23,0,Math.PI,0);ctx.lineTo(cx+bw*.5,by+bh*.68);ctx.quadraticCurveTo(cx,by+bh*.98,cx-bw*.5,by+bh*.68);ctx.closePath();ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,.22)';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(cx,by+bh*.63,bw*.48,bh*.23,0,0,Math.PI);ctx.stroke();
  ctx.fillStyle='rgba(255,255,255,.7)';ctx.beginPath();ctx.ellipse(cx,by,bw*.48,bh*.17,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='rgba(40,72,78,.15)';ctx.beginPath();ctx.ellipse(cx,by+3,bw*.41,bh*.1,0,0,Math.PI*2);ctx.fill();
}
function drawInside(){
  ctx.save();ctx.beginPath();ctx.arc(cx,cy,R-3,0,Math.PI*2);ctx.clip();
  let sky=ctx.createLinearGradient(0,cy-R,0,cy+R);sky.addColorStop(0,'#9bc8d4');sky.addColorStop(.48,'#ddecdf');sky.addColorStop(1,'#f8f7ed');ctx.fillStyle=sky;ctx.fillRect(cx-R,cy-R,R*2,R*2);
  ctx.globalAlpha=.25;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(cx-R*.25,cy-R*.38,R*.33,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
  const shift=Math.sin(yaw)*R*.1;
  ctx.fillStyle='#7da0a0';path([[cx-R,cy+R*.22],[cx-R*.62+shift,cy-R*.04],[cx-R*.35+shift,cy+R*.1],[cx+.05+shift,cy-R*.2],[cx+.5+shift,cy+R*.13],[cx+R,cy-R*.02],[cx+R,cy+R*.7],[cx-R,cy+R*.7]]);ctx.fill();
  ctx.fillStyle='#456f78';path([[cx-R*.86,cy+R*.42],[cx-R*.4+shift,cy+R*.05],[cx-R*.16+shift,cy+R*.25],[cx+.13+shift,cy-R*.51],[cx+.69+shift,cy+R*.34],[cx+R,cy+R*.53],[cx+R,cy+R*.78],[cx-R,cy+R*.78]]);ctx.fill();
  ctx.fillStyle='#eef4ec';path([[cx-R*.16+shift,cy+R*.25],[cx+.13+shift,cy-R*.51],[cx+.31+shift,cy-R*.18],[cx+.21+shift,cy-R*.24],[cx+.1+shift,cy-R*.13],[cx+.03+shift,cy-R*.22],[cx-R*.08+shift,cy+R*.18],[cx+.03+shift,cy+R*.1],[cx+.12+shift,cy+R*.28]]);ctx.fill();
  ctx.fillStyle='#b9ced0';path([[cx+.13+shift,cy-R*.51],[cx+.69+shift,cy+R*.34],[cx+.3+shift,cy+R*.04],[cx+.37+shift,cy-R*.05],[cx+.22+shift,cy-R*.14]]);ctx.fill();
  ctx.fillStyle='#f4f5ea';ctx.beginPath();ctx.ellipse(cx,cy+R*.56,R*1.1,R*.31,0,0,Math.PI*2);ctx.fill();
  trees.sort((a,b)=>a.z-b.z).forEach(t=>{const xx=cx+(t.a+Math.sin(yaw+t.z)*.1)*R*.57,yy=cy+R*(.38+t.z*.22);tree(xx,yy,7*t.s*(.8+t.z*.3),.55+t.z*.35)});
  flakes.forEach(f=>{f.y+=f.v*(1+energy*4);f.x+=Math.sin(time*.001+f.w)*.00045*(1+energy*2);if(f.y>1){f.y=-1;f.x=rand(-1,1);f.z=rand(-1,1)}if(f.x>1)f.x=-1;if(f.x<-1)f.x=1;const zz=(f.z+1)/2,px=cx+f.x*R*.88*(.75+zz*.25)+Math.sin(yaw+f.z)*R*.025,py=cy+f.y*R*.9;const inside=Math.hypot(px-cx,py-cy)<R*.94;if(inside){ctx.globalAlpha=.35+zz*.6;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(px,py,f.s*(.65+zz*.65),0,Math.PI*2);ctx.fill()}});ctx.globalAlpha=1;
  ctx.restore();
}
function drawGlass(){
  let rim=ctx.createRadialGradient(cx-R*.3,cy-R*.35,R*.1,cx,cy,R);rim.addColorStop(0,'rgba(255,255,255,0)');rim.addColorStop(.75,'rgba(255,255,255,.025)');rim.addColorStop(.96,'rgba(218,242,242,.2)');rim.addColorStop(1,'rgba(65,105,116,.3)');ctx.fillStyle=rim;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fill();
  ctx.strokeStyle='rgba(255,255,255,.88)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(cx,cy,R-2,-2.75,.2);ctx.stroke();ctx.strokeStyle='rgba(40,81,94,.28)';ctx.beginPath();ctx.arc(cx,cy,R-1,.2,2.6);ctx.stroke();
  ctx.save();ctx.translate(cx-R*.44,cy-R*.27);ctx.rotate(-.52);let hi=ctx.createLinearGradient(0,-R*.35,0,R*.35);hi.addColorStop(0,'rgba(255,255,255,0)');hi.addColorStop(.5,'rgba(255,255,255,.48)');hi.addColorStop(1,'rgba(255,255,255,0)');ctx.fillStyle=hi;ctx.beginPath();ctx.ellipse(0,0,R*.035,R*.34,0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.fillStyle='rgba(255,255,255,.8)';ctx.beginPath();ctx.arc(cx+R*.46,cy-R*.51,R*.025,0,Math.PI*2);ctx.fill();
}
function loop(t){time=t;targetYaw*=.985;yaw+=(targetYaw-yaw)*.08;energy*=.985;ctx.clearRect(0,0,W,H);drawBase();drawInside();drawGlass();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function start(e){drag=true;lastX=e.clientX;scene.setPointerCapture(e.pointerId);hint.style.opacity='.15'}function move(e){if(!drag)return;const dx=e.clientX-lastX;lastX=e.clientX;targetYaw+=dx*.012;energy=Math.min(1,energy+Math.abs(dx)*.008)}function end(){drag=false}
scene.addEventListener('pointerdown',start);scene.addEventListener('pointermove',move);scene.addEventListener('pointerup',end);scene.addEventListener('pointercancel',end);
document.getElementById('shake').onclick=function(){energy=1;flakes.forEach(f=>{f.y=rand(-1,1);f.x=rand(-1,1);f.v=rand(.002,.006)});targetYaw+=.35};
document.getElementById('reset').onclick=function(){targetYaw=0;energy=.25};
const clock=document.getElementById('clock');function setClock(){const d=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',hour:'2-digit',minute:'2-digit',hour12:false}).format(d);clock.textContent=parts}setClock();setInterval(setClock,30000);
})();
</script>
</body>
</html>"}
